CREATE TABLE projected_citation_edge WITH (format='PARQUET',write_compression='ZSTD') AS SELECT try_cast(regexp_extract(w.id, '[A-Z]([0-9]+)$', 1) AS bigint) AS citing_work_id,try_cast(regexp_extract(ref, '[A-Z]([0-9]+)$', 1) AS bigint) AS cited_work_id,min(CASE WHEN w.publication_year BETWEEN 0 AND 65535 THEN w.publication_year END) AS citing_year FROM raw_works w CROSS JOIN UNNEST(w.referenced_works) AS u(ref) WHERE try_cast(regexp_extract(w.id, '[A-Z]([0-9]+)$', 1) AS bigint) IS NOT NULL AND try_cast(regexp_extract(ref, '[A-Z]([0-9]+)$', 1) AS bigint) IS NOT NULL GROUP BY try_cast(regexp_extract(w.id, '[A-Z]([0-9]+)$', 1) AS bigint),try_cast(regexp_extract(ref, '[A-Z]([0-9]+)$', 1) AS bigint);
